import{_ as e,o as i,c as l,ag as s}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":1775981700000}'),n={name:"faq/index.md"};function r(t,a,o,p,d,h){return i(),l("div",null,[...a[0]||(a[0]=[s(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="问题概览" tabindex="-1">问题概览 <a class="header-anchor" href="#问题概览" aria-label="Permalink to &quot;问题概览&quot;">​</a></h2><p>以下是使用 LiveRecorder 时常见的问题和解决方案。</p><h3 id="问题分类" tabindex="-1">问题分类 <a class="header-anchor" href="#问题分类" aria-label="Permalink to &quot;问题分类&quot;">​</a></h3><ul><li><a href="./follow.html">跟随问题</a> - 跟随相关问题</li><li><a href="./performance.html">性能问题</a> - 性能相关问题</li><li><a href="./privacy.html">隐私问题</a> - 隐私相关问题</li><li><a href="./config.html">配置问题</a> - 配置相关问题</li></ul><h2 id="快速解答" tabindex="-1">快速解答 <a class="header-anchor" href="#快速解答" aria-label="Permalink to &quot;快速解答&quot;">​</a></h2><h3 id="录制者画面出现瞬移怎么办" tabindex="-1">录制者画面出现瞬移怎么办？ <a class="header-anchor" href="#录制者画面出现瞬移怎么办" aria-label="Permalink to &quot;录制者画面出现瞬移怎么办？&quot;">​</a></h3><p>尝试调低 <code>follow-speed</code> 值（如 0.2），或增大 <code>distance</code> 让镜头更远。如果目标玩家频繁传送，这是正常行为——插件会自动传送录制者到新位置。</p><h3 id="录制者跟不上目标玩家怎么办" tabindex="-1">录制者跟不上目标玩家怎么办？ <a class="header-anchor" href="#录制者跟不上目标玩家怎么办" aria-label="Permalink to &quot;录制者跟不上目标玩家怎么办？&quot;">​</a></h3><p>调高 <code>follow-speed</code> 值（如 0.5），或减小 <code>distance</code> 让镜头更近。</p><h3 id="如何让录制者使用旁观者模式" tabindex="-1">如何让录制者使用旁观者模式？ <a class="header-anchor" href="#如何让录制者使用旁观者模式" aria-label="Permalink to &quot;如何让录制者使用旁观者模式？&quot;">​</a></h3><p>在绑定录制者之前，先将录制者设为旁观者模式：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gamemode spectator CameraMan</span></span>
<span class="line"><span>/lr bind CameraMan Steve auto</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="目标玩家下线了怎么办" tabindex="-1">目标玩家下线了怎么办？ <a class="header-anchor" href="#目标玩家下线了怎么办" aria-label="Permalink to &quot;目标玩家下线了怎么办？&quot;">​</a></h3><p>插件会自动将录制者切换到其他在线目标。如果没有其他目标，跟随会暂停，录制者会收到通知。</p><h3 id="可以同时跟拍多个目标吗" tabindex="-1">可以同时跟拍多个目标吗？ <a class="header-anchor" href="#可以同时跟拍多个目标吗" aria-label="Permalink to &quot;可以同时跟拍多个目标吗？&quot;">​</a></h3><p>一个录制者同一时间只能跟拍一个目标。但你可以绑定多个录制者到不同目标，实现多机位效果。</p><h3 id="如何关闭录制者的操作限制" tabindex="-1">如何关闭录制者的操作限制？ <a class="header-anchor" href="#如何关闭录制者的操作限制" aria-label="Permalink to &quot;如何关闭录制者的操作限制？&quot;">​</a></h3><p>在 <code>config.yml</code> 中将对应的限制项设为 <code>false</code>，然后执行 <code>/lr reload</code>。</p><h3 id="如何禁用录制者隐身功能" tabindex="-1">如何禁用录制者隐身功能？ <a class="header-anchor" href="#如何禁用录制者隐身功能" aria-label="Permalink to &quot;如何禁用录制者隐身功能？&quot;">​</a></h3><p>在 <code>config.yml</code> 中设置：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">privacy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  recorder-invisible</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>然后执行 <code>/lr reload</code>。</p><h3 id="玩家如何拒绝被直播" tabindex="-1">玩家如何拒绝被直播？ <a class="header-anchor" href="#玩家如何拒绝被直播" aria-label="Permalink to &quot;玩家如何拒绝被直播？&quot;">​</a></h3><p>玩家可以使用以下方式拒绝：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 拒绝当前的直播请求</span></span>
<span class="line"><span>/lr decline</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 永久拒绝被直播</span></span>
<span class="line"><span>/lr setprivacy decline</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="隐私数据保存在哪里" tabindex="-1">隐私数据保存在哪里？ <a class="header-anchor" href="#隐私数据保存在哪里" aria-label="Permalink to &quot;隐私数据保存在哪里？&quot;">​</a></h3><p>隐私设置和直播日志保存在 <code>plugins/LiveRecorder/privacy.db</code> SQLite 数据库文件中。</p><h3 id="如何清理旧的直播日志" tabindex="-1">如何清理旧的直播日志？ <a class="header-anchor" href="#如何清理旧的直播日志" aria-label="Permalink to &quot;如何清理旧的直播日志？&quot;">​</a></h3><p>插件会自动保留最近 100 条日志，超出限制的会在下次启动时自动清理。也可以手动删除数据库文件（不建议）。</p><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><p>如果以上问题没有解决你的问题，可以：</p><ol><li><strong>查看详细文档</strong> - <a href="./../">文档首页</a></li><li><strong>提交 Issue</strong> - <a href="https://github.com/httye/LiveRecorder/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><strong>联系开发者</strong> - 通过 GitHub 联系</li></ol><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>报告问题时，请提供以下信息：</p><ol><li><p><strong>服务器信息</strong></p><ul><li>服务端类型和版本（Spigot/Paper, 1.16+）</li><li>Java 版本</li></ul></li><li><p><strong>插件版本</strong></p><ul><li>LiveRecorder 版本号</li></ul></li><li><p><strong>问题描述</strong></p><ul><li>详细描述问题</li><li>重现步骤</li><li>期望行为</li></ul></li><li><p><strong>错误日志</strong></p><ul><li>控制台错误信息</li><li>相关配置</li></ul></li><li><p><strong>截图/视频</strong></p><ul><li>问题截图或录屏</li></ul></li></ol><h2 id="贡献答案" tabindex="-1">贡献答案 <a class="header-anchor" href="#贡献答案" aria-label="Permalink to &quot;贡献答案&quot;">​</a></h2><p>如果你有更好的解决方案或发现新的问题，欢迎：</p><ol><li>在 GitHub 上提交 PR 修改文档</li><li>在 Issues 中分享你的经验</li><li>帮助其他用户解决问题</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./../guide/getting-started.html">入门指南</a> - 快速上手插件</li><li><a href="./../commands/index.html">命令参考</a> - 查看所有可用命令</li><li><a href="./../config/index.html">配置详解</a> - 详细配置说明</li></ul>`,41)])])}const b=e(n,[["render",r]]);export{u as __pageData,b as default};
